import { useState, useEffect } from "react";
import { getAll, create, update, remove } from "./api/studentApi";
import StudentForm from "./components/StudentForm";
import StudentList from "./components/StudentList";
import "./App.css";

function App() {
  const [students, setStudents] = useState([]);
  const [editingStudent, setEditingStudent] = useState(null);
  const [apiError, setApiError] = useState("");

  const fetchStudents = () => {
    getAll().then((res) => setStudents(res.data));
  };

  useEffect(() => {
    fetchStudents();
  }, []);

  const handleSave = (student) => {
    if (editingStudent) {
      update(editingStudent.id, student).then(() => {
        setEditingStudent(null);
        fetchStudents();
      });
    } else {
      create(student).then(() => fetchStudents());
    }
  };

  const handleDelete = (id) => {
    remove(id).then(() => fetchStudents());
  };

  return (
    <div>
      <h1>Öğrenci Takip Sistemi</h1>
      <StudentForm
        onSave={handleSave}
        editingStudent={editingStudent}
        onCancel={() => setEditingStudent(null)}
      />
      <StudentList
        students={students}
        onEdit={setEditingStudent}
        onDelete={handleDelete}
      />
    </div>
  );
}

export default App;
